import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, List<double>> calculateAverages(List<Transaction> transactions) {
  Map<String, List<double>> coinData = {};

  for (var transaction in transactions) {
    if (!coinData.containsKey(transaction.coinName)) {
      coinData[transaction.coinName] = [0.0, 0.0];
    }
    coinData[transaction.coinName][0] += transaction.profitLoss;
