public class MagneticFieldAnalyzer {
    public static void main(String[] args) {
        double[][] data = new double[5][4]; // 5 rows for locations, 4 columns for latitude, longitude, and magnetic field intensity

        try (BufferedReader br = new BufferedReader(new FileReader("magnetic_field_data.txt"))) {
            String line;
