  return (
    <div className="object-view">
      <label htmlFor="asset-select">Asset:</label>
      <select id="asset-select" value={model.selectedAsset} onChange={(e) => model.setSelectedAsset(e.target.value)}>
        {model.availableAssets.map((asset, index) => (
          <option key={index} value={asset}>
            {asset}
          </option>
