function switchAdjectiveOrder(sentence) {
  // Define a list of common English adjectives for identification
  const adjectives = ["a", "an", "the", /^[A-Z][a-z]*[^ ]+ [A-Z][a-z]*[^ ]+/g];

  // Split the sentence into words
  const words = sentence.split(" ");

  // Find all pairs of consecutive adjectives and switch their order
  for (let i = 0; i < words.length - 1; i++) {
    if (adjectives.includes(words[i]) && adjectives.includes(words[i + 1])) {
      const temp = words[i];
      words[i] = words[i + 1];
      words[i + 1] = temp;
    }
  }

  // Join the words back into a single sentence
  return words.join(" ") + ".";
}

// Test the function
console.log(switchAdjectiveOrder("Beautiful green trees are in the park")); // "Green beautiful trees are in the park."
```

