#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a = 0, int b = 1) {
    if (n <= 0) {
        throw invalid_argument("Number of sequence elements must be positive.");
    }
    if (n == 1) {
        cout << a << endl;
        return;
    }
    fibonacci(n - 1, b, a + b);
    cout << b << (n > 2 ? ", " : "");
}

int main() {
    int first, second, numElements;

    cout << "Enter the first number in the sequence: ";
    cin >> first;
    if (!isdigit(first)) {
        cerr << "Invalid input. First number must be an integer.";
        return 1;
    }

    cout << "Enter the second number in the sequence: ";
    cin >> second;
    if (!isdigit(second)) {
        cerr << "Invalid input. Second number must be an integer.";
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;
    if (numElements < 0) {
        cerr << "Invalid input. Number of sequence elements must be non-negative.";
        return 1;
    }

    try {
        fibonacci(numElements, first, second);
    } catch (const invalid_argument& e) {
        cerr << e.what();
        return 1;
    }

    return 0;
}
```

