 Here's an example of creating an app with professional access permission guards using Nest.js and TypeORM. Merged into a single `index.js` file. I assume you have basic setup done.

```javascript
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import * as JWT from 'jsonwebtoken';
import { JwtAuthGuard } from './auth/jwt-auth.guard';
import { Roles } from './decorators/roles.decorator';
import { GqlRolesGuard } from './guards/gql-roles.guard';
import { RolesEnum } from './enums/roles.enum';

declare global {
  namespace Express {
    interface Request {
      user: any;
    }
  }
}

const app = async () => {
  const app = await NestFactory.create(AppModule);

  app.useGlobalGuards(new JwtAuthGuard());

  app.use('/graphql', (req, res, next) => {
    const role = req.user.role;

    if (!role) return res.status(401).send('Unauthorized');

    next();
  });

  app.useGlobalGuards(new GqlRolesGuard());

  const port = process.env.PORT || 3000;

  await app.listen(port, () => console.log(`Listening on port ${port}`));
};

app();

// auth.guard.ts
export class JwtAuthGuard implements CanActivateFn {
  canActivate(_context: ExecutionContext): boolean | Promise<boolean> | Observable<boolean> | Promise<Observable<boolean>> {
    const request = _context.switchToHttp().getRequest();

    try {
      const token = request.headers.authorization.split(' ')[1];
      const decoded = JWT.verify(token, process.env.JWT_SECRET);
      request.user = decoded;
      return true;
    } catch (err) {
      throw new UnauthorizedException();
    }
  }
}

