const TemperatureConverter = ({ initialValue, fromUnit, toUnit }) => {
  const { temperature, convert } = useTemperatureConverter(initialValue, fromUnit, toUnit);

  return (
    <div>
      <p>Current Temperature: {temperature} {toUnit}</p>
      <button onClick={convert}>Convert</button>
    </div>
  );
};

export default TemperatureConverter;
```

