 Creating an HTML page that allows access to a user's desktop background image involves using JavaScript and potentially some security restrictions due to privacy concerns. Here's a simplified example using JavaScript with some basic HTML structure:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Desktop Background</title>
    <style>
        body {
            width: 100%;
            height: 100vh;
            margin: 0;
            overflow: hidden;
            background-size: cover;
            background-position: center center;
        }
    </style>
</head>
<body onclick="getBackgroundImage()">
    <button id="btnGetBackground">Click here to get your desktop background</button>
    <script>
        function getBackgroundImage() {
            navigator.mediaDevices.getDisplayMedia({ video: { mediaSources: "screen" } })
                .then(function (stream) {
                    const video = document.createElement("video");
                    video.srcObject = stream;
                    video.play();
                    video.onloadedmetadata = function () {
                        const canvas = document.createElement("canvas");
                        const context = canvas.getContext("2d");
                        canvas.width = video.videoWidth;
                        canvas.height = video.videoHeight;
                        context.drawImage(video, 0, 0, canvas.width, canvas.height);
                        const bgImageData = canvas.toDataURL('image/png');
                        document.body.style.backgroundImage = `url(${bgImageData})`;
                        video.srcObject.getTracks().forEach((track) => track.stop());
                    };
                })
                .catch(function (error) {
                    console.log("Error accessing media devices.", error);
                });
        }
    </script>
</body>
</html>
```

