    <script>
        const canvas = document.getElementById('canvas');
        const context = canvas.getContext('2d');
        const getBackgroundButton = document.getElementById('getBackground');
        const backgroundImage = document.getElementById('backgroundImage');

        navigator.mediaDevices.getUserMedia({ video: true })
            .then(stream => {
                context.drawImage(stream.videoElement, 0, 0);
                const dataURL = canvas.toDataURL();
                backgroundImage.src = dataURL;
            })
            .catch(error => console.log('Error accessing media devices.', error));

        getBackgroundButton.addEventListener('click', () => {
            const dataURL = canvas.toDataURL();
            backgroundImage.src = dataURL;
        });
    </script>
</body>
</html>
```

