 To retrieve the username from a JSON Web Token (JWT) in an ASP.NET C# WebAPI project, you can follow these steps:

1. First, make sure that you have installed the `Microsoft.IdentityModel.Tokens` NuGet package in your project. If not, install it using the following command in the Package Manager Console:

```
Install-Package Microsoft.IdentityModel.Tokens
```

2. Create a helper method to validate and parse the JWT token. Here's an example of how to implement it:

```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using Microsoft.IdentityModel.Tokens;

public static string GetUsernameFromJwtToken(string jwtToken)
{
    try
    {
        // Define your secret key. Replace it with your own.
        string secretKey = "your_secret_key";

        // Handler for JWT validation
        TokenValidationParameters validationParameters = new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),
            ValidateIssuer = false,
            ValidateAudience = false
        };

        // Decode the JWT and extract the username
        JwtSecurityTokenHandler tokenHandler = new JwtSecurityTokenHandler();
        JwtSecurityToken jwtTokenObj = tokenHandler.ReadJwtToken(jwtToken);

        return jwtTokenObj.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
    }
    catch (Exception ex)
    {
        throw new ArgumentException("Invalid or expired token", nameof(jwtToken));
    }
}
```

