if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Define the product and time frame for identifying loyal customers
$product = 'coffee';
$start_of_week = date('Y-m-d', strtotime('last Monday'));
$end_of_week = date('Y-m-d', strtotime('next Sunday'));

// Query the transaction database to find customers who have purchased the specified product at least three times within the given time frame
$sql = "SELECT customers.name, COUNT(*) as purchase_count
        FROM transactions
        JOIN products ON transactions.product_id = products.id
        JOIN customers ON transactions.customer_id = customers.id
        WHERE products.name = '$product' AND transactions.transaction_date BETWEEN '$start_of_week' AND '$end_of_week'
        GROUP BY customers.id
        HAVING purchase_count >= 3";
$result = $conn->query($sql);

// Display the results
if ($result->num_rows > 0) {
    echo "<table><tr><th>Customer Name</th><th>Number of Purchases</th></tr>";
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>" . $row["name"] . "</td><td>" . $row["purchase_count"] . "</td></tr>";
    }
    echo "</table>";
} else {
    echo "No loyal customers found.";
}

$conn->close();
?>
```

