First, let's define the decorator function:

```typescript
import { CreateDecorator, ExecutionContext } from '@nestjs/common';

@CreateDecorator()
export const NodeEnvCheckMiddleware = (target: Object, key: string, descriptor: PropertyDescriptor) => {
  return {
    ...descriptor,
    async execute(context: ExecutionContext, args: any[], next: Function) {
