export class AppController {
  @Get('/api/:id')
  @UseGuards(AuthGuard())
  @NodeEnvChecker() // apply the decorator here
  getApi(@Param('id') id: string): string {
    return `This is the API endpoint for ID ${id}`;
  }
}
```

