import React, { useState, useEffect } from "react";
import { useCombobox } from "downshift";
import debounce from "lodash.debounce";
import axios from "axios";
import AutoSuggestions from "./AutoSuggestions";

interface Email {
  value: string;
}

const searchEmails = debounce(async (prefix: string): Promise<Email[]> => {
  const response = await axios.get(`/api/emails?prefix=${prefix}`);
  return response.data;
});

const EmailInput: React.FC = () => {
  const [items, setItems] = useState([]);
  const { isOpen, getMenuProps, getComboBoxProps, highlightedIndex, getItemProps } = useCombobox({
    items,
    onChange: (value) => setItems(searchEmails(value).slice(0, 10)), // Limit suggestions to 10 results
  });

  useEffect(() => {
    if (!isOpen && items.length > 0) {
      setItems([]);
    }
  }, [isOpen]);

  return (
    <div>
      <input {...getComboBoxProps()} placeholder="Enter email address" />
      <ul {...getMenuProps()}>
        {items.map((item, index) => (
          <li key={index} {...getItemProps({ item, index })}>
            <span>{item.value}</span>
          </li>
        ))}
        {isOpen && items.length === 0 && <li>No suggestions</li>}
      </ul>
      <AutoSuggestions isOpen={isOpen} highlightedIndex={highlightedIndex}

