```sql
CREATE PROCEDURE ConvertTemp
   @Celsius DECIMAL(5,2),
   @Fahrenheit OUT DECIMAL(5,2)
AS
BEGIN
    SET NOCOUNT ON;

    -- Check if the input value is valid
    IF (@Celsius IS NULL)
    BEGIN
        RAISERROR('Invalid input - Celsius value cannot be null.', 16, 1);
        RETURN;
    END;

    -- Perform temperature conversion
    SET @Fahrenheit = (CAST(@Celsius AS FLOAT) * 1.8) + 32;

    -- Round off the result to two decimal places
