```

Now, create a new file named `removeWidows.js`:

```javascript
import { Document, Paragraph } from 'react-document';
import PropTypes from 'prop-types';

const RemoveWidows = ({ children }) => {
  const parseDocument = (content) => {
    const documentNode = Document.parse(content);
    const nodes = [];

    documentNode.forEach((node) => {
      if (node instanceof Paragraph) {
        const lastLineIndex = node.content.length - 1;
        const lastLineWidth = node.content[lastLineIndex].length * 6.5; // Assuming each character occupies 6.5px horizontally
        const totalLineWidth = node.content.map((line) => line.length * 6.5).reduce((a, b) => a + b, 0);

        if (Math.abs(totalLineWidth - node.style.fontSize.value.replace('px', '').split(' ')[0] * node.content.length) < 1) {
          node.content[lastLineIndex].addAttribute('data-widow', true);
        }

        nodes.push(node);
      } else {
        nodes.push(node);
      }
    });

    return documentNode;
  };

  return <Document nodes={parseDocument(children)} />;
};

RemoveWidows.propTypes = {
  children: PropTypes.node,
};

export default RemoveWidows;
```

