```javascript
import React from 'react';

const MIN_LINE_LENGTH = 3; // Minimum number of characters per line

const removeWidows = (text, lineHeight) => {
  const words = text.split(' ');
  let lastLine = [];

  for (let i = words.length - 1; i >= 0; i--) {
    if (lastLine.length + words[i].length > MIN_LINE_LENGTH && i !== 0) {
      // If adding the current word would result in a line with more than the minimum length, break out of the loop
      break;
    } else {
      lastLine.push(words[i]);
      words.splice(i, 1);
    }
  }

  return [words.join(' ') + ' ' + lastLine.join(' ')].map((line, index) => (
    <p key={index} style={{ lineHeight }}>
      {line.trim()}
    </p>
  )).reverse();
};

export default function WidowFreeParagraph({ children, lineHeight }) {
  return (
    <div style={{ lineHeight }}>
      {removeWidows(children.toString(), lineHeight).map((para, i) => (
        <p key={i}>{para}</p>
      ))}
    </div>
  );
}

