    screen_hint: 'signup', // show sign-up and sign-in options side by side
  });
}

window.onload = function () {
  if (auth0.isAuthenticated()) {
    getSession();
  } else {
    loginWithAuth0();
  }
};
```

Finally, you can use the `getSession()` function to retrieve the user's session information:

```javascript
